cases = {n: [] for n in range(1, 7)}

def add(n, tags, question, sql, notes):
    cases[n].append(dict(id=f'B2-T{n}-{len(cases[n])+1:03}', difficulty=GROUPS[n-1], tags=tags.split(','), question=question, gold_sql=sql.strip().rstrip(';')+';', notes=notes))

# T1: projection, predicate and deterministic ordering across business domains.
add(1,'orders,status,null', '查看全部状态中，已审核但仍未交给承运商的订单，取审核时间最早的30笔；审核时间必须已知。只输出订单号、状态和审核时间，时间相同按订单号升序。',
'''SELECT order_id, order_status, order_approved_at FROM orders WHERE order_approved_at IS NOT NULL AND order_delivered_carrier_date IS NULL ORDER BY order_approved_at, order_id LIMIT 30''', '物理粒度为orders一行一订单；包括取消和不可用状态；不推断发货状态。')
add(1,'products,dimensions,topk', '找出长度、高度、宽度均已知且三边都至少40厘米的商品，按重量从重到轻取前25个；重量未知的不参加。只输出商品ID、重量克数和三边厘米数，重量相同按商品ID升序。',
'''SELECT product_id, product_weight_g, product_length_cm, product_height_cm, product_width_cm FROM products WHERE product_length_cm >= 40 AND product_height_cm >= 40 AND product_width_cm >= 40 AND product_weight_g IS NOT NULL ORDER BY product_weight_g DESC, product_id LIMIT 25''', '数量单位是商品记录，不是订单销量；最重候选排除NULL重量。')
add(1,'members,status,topk', '在冻结会员（status=2）中，列出积分已知且不少于1500的前40名，按积分降序、会员ID升序。只输出会员ID、自然人标识和积分，不按自然人再合并。',
'''SELECT member_id, customer_unique_id, points FROM members WHERE status=2 AND points>=1500 ORDER BY points DESC,member_id LIMIT 40''','物理身份为member_id；状态2是冻结；积分未知不入候选。')
add(1,'coupons,discount,bounds', '列出满减券中最低订单金额已知且在100至300之间（两端都含）的券，按最低订单金额升序、券ID升序取前35条。只输出券ID、券码、优惠额度和最低订单金额。',
'''SELECT coupon_id,coupon_code,discount_value,min_order_amount FROM coupons WHERE discount_type='fixed' AND min_order_amount BETWEEN 100 AND 300 ORDER BY min_order_amount,coupon_id LIMIT 35''','按券记录；fixed为满减，不混入percent券；未知门槛排除。')
add(1,'shipments,state,null', '从运输中记录（status=2）中找出已有发货时间但尚无签收时间的记录，按发货时间升序、运输记录ID升序取前40条。只输出运输记录ID、订单号、承运商和发货时间。',
'''SELECT shipment_id,order_id,carrier,shipped_at FROM shipments WHERE status=2 AND shipped_at IS NOT NULL AND delivered_at IS NULL ORDER BY shipped_at,shipment_id LIMIT 40''','一行一shipment_id；不借用订单表签收时间，不额外过滤订单状态。')
add(1,'refunds,status,topk', '在已通过退款（status=2）中，取退款金额已知且大于150的最高30笔。只输出退款ID、订单号、申请金额和原因编码，金额降序、退款ID升序；申请金额按退款单字段，不加运费。',
'''SELECT refund_id,order_id,refund_amount,reason_code FROM refunds WHERE status=2 AND refund_amount>150 ORDER BY refund_amount DESC,refund_id LIMIT 30''','粒度refund_id；不把refund_items金额混入申请金额，不筛订单状态。')
add(1,'support_tickets,priority,null', '列出优先级为紧急（4）、解决时间仍为空的工单，按创建时间从早到晚取前30条，创建时间未知者不入选。只输出工单ID、订单号、创建时间；并列按工单ID升序。',
'''SELECT ticket_id,order_id,created_at FROM support_tickets WHERE priority=4 AND resolved_at IS NULL AND created_at IS NOT NULL ORDER BY created_at,ticket_id LIMIT 30''','按解决时间是否为空判断，不用工单status替代；一行一工单。')
add(1,'search_logs,zero_results,topk', '查看有点击商品但搜索结果数为0的搜索日志，按搜索时间降序、日志ID降序取最近30条，搜索时间未知不参与。只输出日志ID、搜索词、点击商品ID和搜索时间。',
'''SELECT log_id,keyword,clicked_product_id,searched_at FROM search_logs WHERE result_count=0 AND clicked_product_id IS NOT NULL AND searched_at IS NOT NULL ORDER BY searched_at DESC,log_id DESC LIMIT 30''','不纠正可能矛盾的原始事实；一条日志计一次。')
add(1,'inventory,safety_stock,topk', '按仓库商品库存记录查找库存量低于安全库存的项，两项数量都要已知。按缺口（安全库存减库存量）降序取前40项，并列按仓库ID、商品ID升序。只输出仓库ID、商品ID和缺口。',
'''SELECT warehouse_id,product_id,safety_stock-quantity AS shortage FROM inventory WHERE quantity IS NOT NULL AND safety_stock IS NOT NULL AND quantity<safety_stock ORDER BY shortage DESC,warehouse_id,product_id LIMIT 40''','库存身份是(warehouse_id,product_id)；不合并跨仓库存。')
add(1,'product_price_history,absolute_delta,topk', '查找新旧价格均已知且新价比旧价至少下降50的调价记录，按绝对降价金额降序取前30次；并列按历史记录ID升序。只输出历史记录ID、商品ID和降价金额，不计算百分比。',
'''SELECT history_id,product_id,old_price-new_price AS decrease_amount FROM product_price_history WHERE old_price IS NOT NULL AND new_price IS NOT NULL AND old_price-new_price>=50 ORDER BY decrease_amount DESC,history_id LIMIT 30''','一行一次价格变更；金额差为old_price-new_price，允许原价为0。')
add(1,'order_reviews,comment,topk', '查看评分为3且评价正文为空（SQL NULL）的评价，按评价创建时间降序取最近20条；时间未知排除，并列按评价ID、订单号升序。只输出评价ID、订单号和评价创建时间。',
'''SELECT review_id,order_id,review_creation_date FROM order_reviews WHERE review_score=3 AND review_comment_message IS NULL AND review_creation_date IS NOT NULL ORDER BY review_creation_date DESC,review_id,order_id LIMIT 20''','评价完整主键是(review_id,order_id)，不按review_id单独去重；空字符串不等于NULL。')
add(1,'order_payments,installments,topk', '从信用卡支付记录中取分期期数已知且至少8期的最高25笔支付金额；支付金额未知不入选。只输出订单号、支付序号、期数和支付金额，金额降序，再按订单号、支付序号升序；包含全部订单状态。',
'''SELECT order_id,payment_sequential,payment_installments,payment_value FROM order_payments WHERE payment_type='credit_card' AND payment_installments>=8 AND payment_value IS NOT NULL ORDER BY payment_value DESC,order_id,payment_sequential LIMIT 25''','支付身份为(order_id,payment_sequential)；付款金额不是商品金额，不加运费。')
add(1,'settlements,status,topk', '列出已结算（status=2）且应结净额大于1000的结算单，按净额降序取前30张，并列按结算ID升序。只输出结算ID、卖家ID、账期开始日和应结净额，不重新扣佣金。',
'''SELECT settlement_id,seller_id,period_start,net_amount FROM settlements WHERE status=2 AND net_amount>1000 ORDER BY net_amount DESC,settlement_id LIMIT 30''','直接读取net_amount；一张结算单计一次，不关联结算明细。')
add(1,'shipping_addresses,default,records', '查看默认收货地址中州代码为RJ且城市已知的记录，按城市、地址ID升序取前40条。只输出地址ID、客户关联键customer_id、城市；不将客户关联键当自然人，也不筛选订单。',
'''SELECT address_id,customer_id,city FROM shipping_addresses WHERE is_default IS TRUE AND state='RJ' AND city IS NOT NULL ORDER BY city,address_id LIMIT 40''','按address_id读取地址记录；不以customers里的城市代替地址城市。')
add(1,'referrals,null,topk', '查看推荐人和被推荐人都已知、尚未转化且已记录正奖励金额的推荐，按创建时间升序取最早20条；创建时间未知排除，并列按推荐ID升序。只输出推荐ID、两端会员ID和奖励金额。',
'''SELECT referral_id,referrer_member_id,invitee_member_id,reward_amount FROM referrals WHERE referrer_member_id IS NOT NULL AND invitee_member_id IS NOT NULL AND converted_at IS NULL AND reward_amount>0 AND created_at IS NOT NULL ORDER BY created_at,referral_id LIMIT 20''','不因未转化就强制把已有奖励改成0；物理粒度referral_id。')
add(1,'campaigns,budget,topk', '在状态为已结束（3）的营销活动中，找出预算已知且为正的预算最低12个。只输出活动ID、活动名称、活动类型和预算，预算升序、活动ID升序；不把同名活动合并。',
'''SELECT campaign_id,campaign_name,campaign_type,budget FROM campaigns WHERE status=3 AND budget>0 ORDER BY budget,campaign_id LIMIT 12''','活动身份为campaign_id，最低值只从已知正预算候选选择。')
add(1,'brands,country,records', '列出品牌国家原始代码为BR的前25个品牌，按品牌名称升序（名称未知排末）、品牌ID升序。只输出品牌ID和品牌名称，国家值按原文精确匹配。',
'''SELECT brand_id,brand_name FROM brands WHERE country='BR' ORDER BY brand_name NULLS LAST,brand_id LIMIT 25''','品牌名不是唯一身份；不做国家名翻译或模糊匹配。')
add(1,'geolocation,coordinates,distinct', '在地理坐标表中找出州代码为SC、纬度和经度都已知的不同邮编前缀，按邮编前缀升序取前40个；邮编前缀未知排除。只输出邮编前缀，不输出或选择某一个坐标点。',
'''SELECT DISTINCT geolocation_zip_code_prefix FROM geolocation WHERE geolocation_state='SC' AND geolocation_lat IS NOT NULL AND geolocation_lng IS NOT NULL AND geolocation_zip_code_prefix IS NOT NULL ORDER BY geolocation_zip_code_prefix LIMIT 40''','同一邮编可有多坐标行，此题只去重邮编，不与交易事实连接。')
add(1,'ticket_messages,sender,topk', '列出发送方原始值为customer且正文不是SQL NULL的最近35条工单消息；创建时间未知不参与，按创建时间降序、消息ID降序。只输出消息ID、工单ID、创建时间；空字符串正文仍算存在。',
'''SELECT message_id,ticket_id,created_at FROM ticket_messages WHERE sender_type='customer' AND content IS NOT NULL AND created_at IS NOT NULL ORDER BY created_at DESC,message_id DESC LIMIT 35''','消息身份message_id；不把多个消息合并成工单数。')
add(1,'warehouses,capacity,topk', '取容量已知且大于0的容量最小8座仓库，按容量升序、仓库ID升序。只输出仓库ID、仓库名称、州代码和容量；同名仓库分别保留。',
'''SELECT warehouse_id,warehouse_name,region_code,capacity FROM warehouses WHERE capacity>0 ORDER BY capacity,warehouse_id LIMIT 8''','单位是仓库记录，不计算当前库存；最小候选排除未知/非正容量。')

# T2: one-table aggregates; each grain and missing-value policy is explicit.
add(2,'orders,timestamps,group', '按原始订单状态统计全部订单中“已有发货时间但签收时间为空”的订单数，只输出状态和订单数，状态升序、NULL状态最后；没有符合记录的状态不补0。',
'''SELECT order_status,COUNT(*) AS order_count FROM orders WHERE order_delivered_carrier_date IS NOT NULL AND order_delivered_customer_date IS NULL GROUP BY order_status ORDER BY order_status NULLS LAST''','一行一订单；所有状态参与，不用状态推断时间事实。')
add(2,'customers,identity,group', '按客户记录所在州统计客户档案行数和已知自然人标识的去重人数，输出州代码、档案行数、人数；保留NULL州，按档案行数降序、州代码升序且NULL最后。同一自然人在多个州可分别计数。',
'''SELECT customer_state,COUNT(*) AS profile_count,COUNT(DISTINCT customer_unique_id) AS people_count FROM customers GROUP BY customer_state ORDER BY profile_count DESC,customer_state NULLS LAST''','档案单位customer_id；人数单位customer_unique_id，NULL身份不计作人。')
add(2,'products,category,null', '按商品原始类目统计商品数，以及重量已知商品的平均克重（2位小数），只保留至少80个商品的类目。类目NULL单独保留，输出类目、商品数、平均克重，类目升序NULL最后，不给未知重量补0。',
'''SELECT product_category_name,COUNT(*) AS product_count,ROUND(AVG(product_weight_g),2) AS avg_weight_g FROM products GROUP BY product_category_name HAVING COUNT(*)>=80 ORDER BY product_category_name NULLS LAST''','题目明确覆盖原始NULL类目；平均数仅已知重量，数量仍含未知重量商品。')
add(2,'order_payments,payment_grain,aggregate', '按支付方式统计分期期数为1的支付记录条数、支付金额合计及平均金额（2位小数）。只输出这四列，包含全部订单状态；支付方式NULL单列，未知金额忽略且全未知不补0，方式升序NULL最后。',
'''SELECT payment_type,COUNT(*) AS payment_count,SUM(payment_value) AS paid_amount,ROUND(AVG(payment_value),2) AS avg_paid_amount FROM order_payments WHERE payment_installments=1 GROUP BY payment_type ORDER BY payment_type NULLS LAST''','每笔支付一行，非订单数；payment_value是付款事实。')
add(2,'order_items,seller,aggregate', '只按订单明细统计每位卖家的商品行数和商品金额合计（不含运费），取商品行数最多的前18位；并列按卖家ID升序。只输出卖家ID、商品行数、商品金额，不筛订单状态；未知卖家排除，商品金额NULL忽略。',
'''SELECT seller_id,COUNT(*) AS item_rows,SUM(price) AS product_amount FROM order_items WHERE seller_id IS NOT NULL GROUP BY seller_id ORDER BY item_rows DESC,seller_id LIMIT 18''','销量以订单明细行数计；金额不是SUM(DISTINCT price)，不关联订单状态。')
add(2,'members,status,points', '按会员状态统计会员记录数、积分已知记录数和已知积分平均值（2位小数），仅输出这四列；NULL状态保留，状态升序NULL最后，未知积分不当0。',
'''SELECT status,COUNT(*) AS member_count,COUNT(points) AS known_points_count,ROUND(AVG(points),2) AS avg_points FROM members GROUP BY status ORDER BY status NULLS LAST''','member_id为计数单位，不混入会员快照历史。')
add(2,'search_logs,keyword,aggregate', '按非NULL搜索词统计结果数为0的搜索记录条数，取条数最多的前22个搜索词，输出搜索词和条数，条数降序、词升序。不按会员去重，空字符串搜索词保留。',
'''SELECT keyword,COUNT(*) AS zero_result_searches FROM search_logs WHERE result_count=0 AND keyword IS NOT NULL GROUP BY keyword ORDER BY zero_result_searches DESC,keyword LIMIT 22''','计数单位log_id；只统计result_count=0，不把NULL结果数视为0。')
add(2,'shipments,carrier,timestamps', '按承运商统计全部运输记录数和发货、签收时间都已知的记录数，只输出承运商及这两个数量，承运商升序NULL最后；未知承运商单列，不因订单状态删运输记录。',
'''SELECT carrier,COUNT(*) AS shipment_count,COUNT(*) FILTER(WHERE shipped_at IS NOT NULL AND delivered_at IS NOT NULL) AS timed_count FROM shipments GROUP BY carrier ORDER BY carrier NULLS LAST''','shipment_id为事实身份；不要求签收时间一定晚于发货。')
add(2,'refunds,reason,status', '按退款原因编码统计已退款（status=4）的退款单数量和退款金额合计，只输出原因编码、退款单数、金额；原因NULL单列，原因升序NULL最后。金额取退款单refund_amount，不加运费，未知金额忽略，不筛订单状态。',
'''SELECT reason_code,COUNT(*) AS refund_count,SUM(refund_amount) AS refund_amount FROM refunds WHERE status=4 GROUP BY reason_code ORDER BY reason_code NULLS LAST''','单位refund_id，不是去重订单数或退款明细行数。')
add(2,'support_tickets,priority,group', '按工单优先级统计全部工单数，以及解决时间为空的工单数，输出优先级和两个数量；优先级NULL单列，按优先级升序NULL最后，不用工单状态替代解决时间。',
'''SELECT priority,COUNT(*) AS ticket_count,COUNT(*) FILTER(WHERE resolved_at IS NULL) AS unresolved_count FROM support_tickets GROUP BY priority ORDER BY priority NULLS LAST''','每个ticket_id一次；状态不参与筛选。')
add(2,'inventory,warehouse,aggregate', '按仓库ID统计库存表中商品项数、已知库存量合计、低于安全库存的商品项数。输出仓库ID及三个指标，仓库ID升序；仅覆盖库存表实际出现的仓库，未知库存不补0。',
'''SELECT warehouse_id,COUNT(*) AS product_slots,SUM(quantity) AS quantity_total,COUNT(*) FILTER(WHERE quantity<safety_stock) AS below_safety_slots FROM inventory GROUP BY warehouse_id ORDER BY warehouse_id''','一项为仓库商品主键；比较任一值NULL时不认定低库存。')
add(2,'inventory_movements,type,aggregate', '按出入库类型统计库存流水记录数与变动数量合计，只输出类型、记录数、数量合计，类型升序NULL最后；所有时间参与，数量使用原始正负值，不把出库自动改为负数。',
'''SELECT movement_type,COUNT(*) AS movement_count,SUM(quantity) AS quantity_total FROM inventory_movements GROUP BY movement_type ORDER BY movement_type NULLS LAST''','流水身份movement_id，数量正负不推断；未知数量忽略。')
add(2,'coupon_usages,member,topk', '按用券记录上的会员ID汇总优惠金额，取优惠金额已知且合计为正的最高20名，输出会员ID、核销记录数和优惠金额合计。未知会员排除，金额降序、会员ID升序；不去重订单、不筛订单状态。',
'''SELECT member_id,COUNT(*) AS usage_count,SUM(discount_amount) AS discount_total FROM coupon_usages WHERE member_id IS NOT NULL GROUP BY member_id HAVING SUM(discount_amount)>0 ORDER BY discount_total DESC,member_id LIMIT 20''','物理计量单位usage_id；同订单多次核销分别计入金额。')
add(2,'settlements,period,status', '按结算状态统计结算单数、应结净额合计及净额已知的结算单平均净额（2位小数），只输出状态和这三个指标；状态升序NULL最后，不追加或扣减运费、佣金。',
'''SELECT status,COUNT(*) AS settlement_count,SUM(net_amount) AS net_total,ROUND(AVG(net_amount),2) AS avg_net FROM settlements GROUP BY status ORDER BY status NULLS LAST''','只使用结算单net_amount，一单一次；NULL金额不补0。')
add(2,'product_price_history,delta,group', '将每条新旧价格均已知的调价记录分为上涨、下跌、持平三类，按每次新价减旧价判断。输出变动方向和记录数，按方向文字升序；不存在的方向不补0，不按商品去重。',
'''SELECT CASE WHEN new_price>old_price THEN '上涨' WHEN new_price<old_price THEN '下跌' ELSE '持平' END AS direction,COUNT(*) AS change_count FROM product_price_history WHERE old_price IS NOT NULL AND new_price IS NOT NULL GROUP BY 1 ORDER BY direction''','单位history_id；不把任一未知价格当持平。')
add(2,'referrals,reward_buckets,aggregate', '将推荐记录按奖励金额分为“未知”“非正”“0到10”“10到20”“超过20”五档：非正含0和负数，0到10为大于0且不超过10，10到20为大于10且不超过20。输出奖励档、推荐条数、已转化条数和原始奖励总额，按奖励档文字升序；只列实际出现的档，未知档金额合计保持NULL，不因未转化删除奖励。',
'''SELECT CASE WHEN reward_amount IS NULL THEN '未知' WHEN reward_amount<=0 THEN '非正' WHEN reward_amount<=10 THEN '0到10' WHEN reward_amount<=20 THEN '10到20' ELSE '超过20' END AS reward_bucket,COUNT(*) AS referral_count,COUNT(converted_at) AS converted_count,SUM(reward_amount) AS reward_total FROM referrals GROUP BY 1 ORDER BY reward_bucket''','一条referral_id计一次，分桶边界不重叠；转化以converted_at非空判断，不把奖励金额当转化证据。')
add(2,'order_reviews,score,comments', '按评分统计评价记录数，以及正文为SQL NULL的评价记录数，输出评分和两个数量；包括未知评分组，评分升序NULL最后，空字符串正文不当作NULL。',
'''SELECT review_score,COUNT(*) AS review_count,COUNT(*) FILTER(WHERE review_comment_message IS NULL) AS null_body_count FROM order_reviews GROUP BY review_score ORDER BY review_score NULLS LAST''','完整评价主键为(review_id,order_id)，此题每物理行计一次，不按订单去重。')
add(2,'campaigns,type,budget', '按活动类型统计预算已知活动数和预算平均金额（2位小数），输出活动类型、活动数、平均预算；只纳入预算大于0的活动，未知类型单列，类型升序NULL最后，不将活动名称当分组ID。',
'''SELECT campaign_type,COUNT(*) AS campaign_count,ROUND(AVG(budget),2) AS avg_budget FROM campaigns WHERE budget>0 GROUP BY campaign_type ORDER BY campaign_type NULLS LAST''','同名活动分开计数；没有正预算的类型不补行。')
add(2,'shipping_addresses,state,aggregate', '按收货地址自己的州代码统计地址条数、默认地址条数和不同客户关联键customer_id的数量，输出州和三个数量；NULL州保留，州升序NULL最后，未知customer_id不算一个客户关联键，不统计自然人人数。',
'''SELECT state,COUNT(*) AS address_count,COUNT(*) FILTER(WHERE is_default IS TRUE) AS default_count,COUNT(DISTINCT customer_id) AS customer_key_count FROM shipping_addresses GROUP BY state ORDER BY state NULLS LAST''','地址属性来自shipping_addresses，customer_id为关联键计数，不借用customers州。')
add(2,'brands,country,aggregate', '按品牌表原始国家字段统计品牌个数，输出国家和品牌数，按品牌数降序、国家升序且NULL最后。保留NULL国家组，同名品牌按不同品牌ID分别计入，不做国家归一化。',
'''SELECT country,COUNT(*) AS brand_count FROM brands GROUP BY country ORDER BY brand_count DESC,country NULLS LAST''','一品牌ID一次，国家原样分组；没有品牌的国家不凭空补行。')

# T3: explicit historical windows, calendar alignment, and complete tie-breakers.
add(3,'orders,month,coverage', '统计2017年9月1日（含）至2018年3月1日（不含）每个自然月的全部订单数及有审核时间的订单数，输出月份（YYYY-MM）、订单数、已审核时间数；包含取消和不可用状态，只输出实际有订单的月份，月份升序，不补0。',
'''SELECT TO_CHAR(DATE_TRUNC('month',order_purchase_timestamp),'YYYY-MM') AS month,COUNT(*) AS order_count,COUNT(order_approved_at) AS approved_time_count FROM orders WHERE order_purchase_timestamp>='2017-09-01' AND order_purchase_timestamp<'2018-03-01' GROUP BY DATE_TRUNC('month',order_purchase_timestamp) ORDER BY DATE_TRUNC('month',order_purchase_timestamp)''','月份基于下单时间；未知下单时间不属于给定窗口，不用状态代替审核时间。')
add(3,'orders,calendar_comparison,null', '比较2018年1月至6月与2017年同月的有效订单数。只输出两年该月都实际有有效订单的月份（01至06）、2018订单数、2017订单数和数量差（2018减2017），月份升序；有效订单排除canceled和unavailable，不补缺月。',
'''WITH m AS (SELECT EXTRACT(YEAR FROM order_purchase_timestamp)::int AS yr,EXTRACT(MONTH FROM order_purchase_timestamp)::int AS mo,COUNT(*) AS n FROM orders WHERE order_status NOT IN ('canceled','unavailable') AND ((order_purchase_timestamp>='2017-01-01' AND order_purchase_timestamp<'2017-07-01') OR (order_purchase_timestamp>='2018-01-01' AND order_purchase_timestamp<'2018-07-01')) GROUP BY 1,2) SELECT LPAD(a.mo::text,2,'0') AS month,a.n AS orders_2018,b.n AS orders_2017,a.n-b.n AS order_delta FROM m a JOIN m b ON b.mo=a.mo AND b.yr=2017 WHERE a.yr=2018 ORDER BY a.mo''','真实相同自然月对齐，不以相邻记录代替同期；只取两期交集。')
add(3,'search_logs,hour,window', '在2018年5月10日00:00（含）至2018年5月17日00:00（不含）的搜索日志中，按一天中的小时0至23汇总搜索条数和有点击条数。只输出实际出现的小时、两个条数，小时升序；点击以clicked_product_id非NULL判断，不按会员去重。',
'''SELECT EXTRACT(HOUR FROM searched_at)::int AS hour_of_day,COUNT(*) AS search_count,COUNT(clicked_product_id) AS clicked_count FROM search_logs WHERE searched_at>='2018-05-10' AND searched_at<'2018-05-17' GROUP BY 1 ORDER BY 1''','时间按数据库无时区原始时间，窗口左闭右开；没出现的小时不补0。')
add(3,'refunds,quarter,completion', '按退款完成月份统计2018年第二季度已退款（status=4）的退款单数和退款单金额合计，只输出月份YYYY-MM、退款单数、金额，月份升序。完成时间范围为4月1日含至7月1日不含，不按申请日期筛选，不加运费、不筛订单状态，不补缺月。',
'''SELECT TO_CHAR(DATE_TRUNC('month',completed_at),'YYYY-MM') AS month,COUNT(*) AS refund_count,SUM(refund_amount) AS refund_amount FROM refunds WHERE status=4 AND completed_at>='2018-04-01' AND completed_at<'2018-07-01' GROUP BY DATE_TRUNC('month',completed_at) ORDER BY DATE_TRUNC('month',completed_at)''','时间归属为completed_at；金额NULL忽略，单数按refund_id。')
add(3,'product_price_history,latest,pk', '截至2018年7月1日00:00（不含），对每个曾有已知变更时间的商品取最后一次调价；同一时间取history_id最大的记录。只保留最后记录的新价、旧价均已知且新价高于旧价的商品，按涨价金额降序、商品ID升序取前30个。输出商品ID、历史记录ID、变更时间、涨价金额。',
'''WITH ranked AS (SELECT h.*,ROW_NUMBER() OVER(PARTITION BY product_id ORDER BY changed_at DESC,history_id DESC) AS rn FROM product_price_history h WHERE changed_at<'2018-07-01' AND product_id IS NOT NULL) SELECT product_id,history_id,changed_at,new_price-old_price AS increase_amount FROM ranked WHERE rn=1 AND new_price IS NOT NULL AND old_price IS NOT NULL AND new_price>old_price ORDER BY increase_amount DESC,product_id LIMIT 30''','先取真实最后记录再筛价格，不能先挑涨价再称为最后；history_id是真主键。')
add(3,'member_snapshot,latest,pk', '截至2018年6月30日（含），取每位会员最新一条会员快照；同一天取snapshot_id最大者。仅保留该快照积分已知且在2000至4000之间（含两端）的会员，按会员ID升序取前40位。只输出会员ID、快照日期、等级ID、积分；未知会员ID不参与。',
'''WITH s AS (SELECT x.*,ROW_NUMBER() OVER(PARTITION BY member_id ORDER BY snapshot_date DESC,snapshot_id DESC) AS rn FROM member_snapshot x WHERE snapshot_date<='2018-06-30' AND member_id IS NOT NULL) SELECT member_id,snapshot_date,level_id,points FROM s WHERE rn=1 AND points BETWEEN 2000 AND 4000 ORDER BY member_id LIMIT 40''','快照身份snapshot_id；先确定最新快照再筛积分，不回退至更早满足积分的快照。')
add(3,'inventory_movements,month,window', '统计2018年3月1日（含）至6月1日（不含）每个自然月的出库流水（movement_type=2）数量合计和流水条数。只输出月份YYYY-MM、出库数量、流水条数，月份升序；数量按原值相加、NULL忽略，不补没有出库记录的月份。',
'''SELECT TO_CHAR(DATE_TRUNC('month',moved_at),'YYYY-MM') AS month,SUM(quantity) AS outbound_quantity,COUNT(*) AS movement_count FROM inventory_movements WHERE movement_type=2 AND moved_at>='2018-03-01' AND moved_at<'2018-06-01' GROUP BY DATE_TRUNC('month',moved_at) ORDER BY DATE_TRUNC('month',moved_at)''','计量单位为movement_id，不是不同商品数；出库不再反转正负号。')
add(3,'support_tickets,elapsed,window', '统计2018年4月1日含至7月1日不含创建的工单，按创建自然月输出工单数，以及创建和解决时间均已知工单的平均处理小时数（小数小时，2位）。未解决工单仍计入工单数但不计平均；只列实际有工单月份，月份YYYY-MM升序。',
'''SELECT TO_CHAR(DATE_TRUNC('month',created_at),'YYYY-MM') AS month,COUNT(*) AS ticket_count,ROUND(AVG(EXTRACT(EPOCH FROM(resolved_at-created_at))/3600.0),2) AS avg_resolution_hours FROM support_tickets WHERE created_at>='2018-04-01' AND created_at<'2018-07-01' GROUP BY DATE_TRUNC('month',created_at) ORDER BY DATE_TRUNC('month',created_at)''','用完整秒数换小时，不取interval小时分量；不额外过滤工单status。')
add(3,'campaigns,overlap,dates', '查找与2018年6月这个自然月有至少一天重叠的活动，活动的起止日都必须已知、开始日不得晚于结束日，且起止日视为包含当天。只输出活动ID、名称、开始日、结束日，按开始日、活动ID升序；覆盖全部状态，不补缺失日期。',
'''SELECT campaign_id,campaign_name,start_date,end_date FROM campaigns WHERE start_date IS NOT NULL AND end_date IS NOT NULL AND start_date<=end_date AND start_date<DATE '2018-07-01' AND end_date>=DATE '2018-06-01' ORDER BY start_date,campaign_id''','仅合法起止区间参与重叠判断，条件为start<=end、start<下月初且end>=本月初；数据中活动总数小于500，返回完整集合。')
add(3,'settlements,paid_time,month', '按实际打款月份统计2018年1月1日含至9月1日不含的结算单数及应结净额合计，只输出月份YYYY-MM、结算单数、净额，月份升序。不按结算账期筛选，也不额外要求状态=3；不补缺月，净额NULL忽略。',
'''SELECT TO_CHAR(DATE_TRUNC('month',paid_at),'YYYY-MM') AS month,COUNT(*) AS settlement_count,SUM(net_amount) AS net_total FROM settlements WHERE paid_at>='2018-01-01' AND paid_at<'2018-09-01' GROUP BY DATE_TRUNC('month',paid_at) ORDER BY DATE_TRUNC('month',paid_at)''','以真实paid_at而非状态或period_start判断打款归属；一结算单一次。')
add(3,'members,register,last_login', '查找2018年第一季度注册，且最后登录日期不早于2018年7月1日的会员，按注册日期、会员ID升序取前35位。只输出会员ID、注册日期、最后登录日期；未知日期自然排除，会员状态不限。',
'''SELECT member_id,register_date,last_login_date FROM members WHERE register_date>='2018-01-01' AND register_date<'2018-04-01' AND last_login_date>='2018-07-01' ORDER BY register_date,member_id LIMIT 35''','注册窗口为左闭右开，末次登录只有下界；不把会员快照日期当登录日期。')
add(3,'referrals,window,elapsed', '对2018年2月1日含至5月1日不含创建的推荐，按创建月输出推荐条数和创建后7天内完成转化的条数；7天内定义为转化时间大于等于创建时间且小于等于创建时间加7天。月份YYYY-MM升序，不补缺月，不限转化发生的月份。',
'''SELECT TO_CHAR(DATE_TRUNC('month',created_at),'YYYY-MM') AS month,COUNT(*) AS referral_count,COUNT(*) FILTER(WHERE converted_at>=created_at AND converted_at<=created_at+INTERVAL '7 days') AS converted_within_7d FROM referrals WHERE created_at>='2018-02-01' AND created_at<'2018-05-01' GROUP BY DATE_TRUNC('month',created_at) ORDER BY DATE_TRUNC('month',created_at)''','单位推荐记录，NULL或早于创建的转化不算7日内；分母保留全部创建记录。')
add(3,'order_items,shipping_deadline,day', '按发货截止日期统计2018年8月20日含至8月27日不含的订单商品行数及商品金额（不含运费）合计，只输出日期YYYY-MM-DD、商品行数、金额。按截止日升序，包含全部订单状态，不以购买日期筛选，不补缺日。',
'''SELECT TO_CHAR(shipping_limit_date::date,'YYYY-MM-DD') AS deadline_date,COUNT(*) AS item_rows,SUM(price) AS product_amount FROM order_items WHERE shipping_limit_date>='2018-08-20' AND shipping_limit_date<'2018-08-27' GROUP BY shipping_limit_date::date ORDER BY shipping_limit_date::date''','物理明细一行一件；price未知忽略，截止时间归属日期不变时区。')
add(3,'shipments,elapsed,window', '统计2018年6月1日含至8月1日不含发货的运输记录，按发货自然月输出有完整发货与签收时间的记录数和平均发货至签收天数（2位小数）。只纳入签收时间已知记录，跨月签收也计入原发货月；月份YYYY-MM升序，不筛订单或运输状态、不补缺月。',
'''SELECT TO_CHAR(DATE_TRUNC('month',shipped_at),'YYYY-MM') AS month,COUNT(*) AS completed_shipments,ROUND(AVG(EXTRACT(EPOCH FROM(delivered_at-shipped_at))/86400.0),2) AS avg_days FROM shipments WHERE shipped_at>='2018-06-01' AND shipped_at<'2018-08-01' AND delivered_at IS NOT NULL GROUP BY DATE_TRUNC('month',shipped_at) ORDER BY DATE_TRUNC('month',shipped_at)''','事实来源shipments.shipped_at/delivered_at，用EPOCH保留不足一天部分。')
add(3,'order_reviews,latest,complete_pk', '在2018年5月1日含至2018年6月1日不含创建过评价的订单中，每单只取该窗口内创建时间最后的一条评价；同一时间按评价ID降序裁决（完整主键为评价ID加订单号）。找出这条评价评分为1的前30单，按订单号升序；输出订单号、评价ID、创建时间，不筛订单状态。',
'''WITH r AS (SELECT x.*,ROW_NUMBER() OVER(PARTITION BY order_id ORDER BY review_creation_date DESC,review_id DESC,order_id DESC) AS rn FROM order_reviews x WHERE review_creation_date>='2018-05-01' AND review_creation_date<'2018-06-01') SELECT order_id,review_id,review_creation_date FROM r WHERE rn=1 AND review_score=1 ORDER BY order_id LIMIT 30''','范围内最后评价再筛分数，不选择窗口外最新评价，不先过滤1分。')
add(3,'orders,adjacent_calendar_month,coverage', '在2017年11月到2018年4月的有效订单中，按自然月计算订单数相对上一个自然月的数量差。只输出本月和上一个自然月在该范围内都实际有有效订单的月份YYYY-MM与数量差，月份升序；有效订单排除取消和不可用，不补0，不用相邻非空记录冒充上月。',
'''WITH m AS (SELECT DATE_TRUNC('month',order_purchase_timestamp) AS month,COUNT(*) AS n FROM orders WHERE order_status NOT IN ('canceled','unavailable') AND order_purchase_timestamp>='2017-11-01' AND order_purchase_timestamp<'2018-05-01' GROUP BY 1) SELECT TO_CHAR(a.month,'YYYY-MM') AS month,a.n-b.n AS order_delta FROM m a JOIN m b ON b.month=a.month-INTERVAL '1 month' ORDER BY a.month''','月份用真实日期间隔连接，首月没有范围内上月所以不输出。')

# T4: multiple relations with explicitly identified fact grain and attribution.
add(4,'orders,customers,regions', '统计2018年2月1日含至5月1日不含下单的有效订单，按该订单customer_id对应客户记录所在大区汇总订单数。只输出大区和订单数，未知州或没有地区映射的大区保留NULL组，大区升序NULL最后；有效订单排除取消和不可用，不按自然人重选地址。',
'''SELECT r.macro_region,COUNT(*) AS order_count FROM orders o LEFT JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN regions r ON r.region_code=c.customer_state WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-02-01' AND o.order_purchase_timestamp<'2018-05-01' GROUP BY r.macro_region ORDER BY r.macro_region NULLS LAST''','归属链orders.customer_id→customers.customer_state→regions；订单完整保留，不使用自然人反向匹配全部档案。')
add(4,'order_items,sellers,regions', '按卖家所在地大区统计全部订单明细的商品行数和商品金额合计（不含运费），只输出大区及两个指标，大区升序NULL最后。卖家或地区映射缺失保留NULL组，不筛订单状态，不以客户大区归属。',
'''SELECT r.macro_region,COUNT(*) AS item_rows,SUM(oi.price) AS product_amount FROM order_items oi LEFT JOIN sellers s ON s.seller_id=oi.seller_id LEFT JOIN regions r ON r.region_code=s.seller_state GROUP BY r.macro_region ORDER BY r.macro_region NULLS LAST''','金额单位明细原始price，NULL忽略；一条商品行只沿卖家归属链进入一组。')
add(4,'inventory,products,translation', '按库存商品的英文类目统计当前库存数量，取库存合计已知且为正的最高15组，金额无关。只输出英文类目和库存量，库存量降序、英文类目升序NULL最后；保留原始类目未知或无翻译的NULL英文组，库存表每个仓库商品项的quantity直接相加。',
'''SELECT t.product_category_name_english,SUM(i.quantity) AS stock_quantity FROM inventory i LEFT JOIN products p ON p.product_id=i.product_id LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name GROUP BY t.product_category_name_english HAVING SUM(i.quantity)>0 ORDER BY stock_quantity DESC,t.product_category_name_english NULLS LAST LIMIT 15''','跨仓合并数量但不重复商品品牌；翻译缺失与原始类目NULL都按输出维度为NULL归组。')
add(4,'members,member_levels,zero', '列出所有会员等级定义，按等级ID输出等级ID、等级名称以及当前冻结会员（status=2）的会员记录数。没有冻结会员的等级显示0；会员level_id为空或不在等级表的记录不归入任一等级，不输出额外未知等级。',
'''SELECT l.level_id,l.level_name,COUNT(m.member_id) AS frozen_members FROM member_levels l LEFT JOIN members m ON m.level_id=l.level_id AND m.status=2 GROUP BY l.level_id,l.level_name ORDER BY l.level_id''','维度全集来自等级定义，因此可证明零值；COUNT会员主键而非COUNT(*)。')
add(4,'campaigns,coupons,zero', '列出状态为已结束（3）的每个活动及其满减券（discount_type=fixed）数量，输出活动ID、活动名称、满减券数，活动ID升序。没有满减券的活动显示0；同名活动分开，不按券有效期筛选。',
'''SELECT c.campaign_id,c.campaign_name,COUNT(cp.coupon_id) AS fixed_coupon_count FROM campaigns c LEFT JOIN coupons cp ON cp.campaign_id=c.campaign_id AND cp.discount_type='fixed' WHERE c.status=3 GROUP BY c.campaign_id,c.campaign_name ORDER BY c.campaign_id''','活动ID为维度身份，左连接条件保留零券活动；不补不存在的活动。')
add(4,'coupon_usages,coupons,campaigns', '在2018年3月1日含至6月1日不含核销的用券记录中，按券所属活动统计优惠金额合计及核销条数，取优惠金额最高12个活动（只比较已知合计）。输出活动ID、活动名称、优惠金额、核销条数；只计能匹配券和活动的记录，不筛订单状态，金额降序再活动ID升序。',
'''SELECT c.campaign_id,c.campaign_name,SUM(u.discount_amount) AS discount_total,COUNT(*) AS usage_count FROM coupon_usages u JOIN coupons cp ON cp.coupon_id=u.coupon_id JOIN campaigns c ON c.campaign_id=cp.campaign_id WHERE u.used_at>='2018-03-01' AND u.used_at<'2018-06-01' GROUP BY c.campaign_id,c.campaign_name HAVING SUM(u.discount_amount) IS NOT NULL ORDER BY discount_total DESC,c.campaign_id LIMIT 12''','一条usage_id一次，discount_amount为优惠事实；不按订单明细行复制金额。')
add(4,'refund_items,order_items,products', '对能按订单号加明细序号匹配到商品明细的退款明细，按商品原始类目汇总退款件数和退款明细金额，取退款件数最多的前18类。输出类目、退款件数、退款金额；类目NULL保留，件数合计未知不参与排名，并列按类目升序NULL最后。不筛退款或订单状态，不加运费。',
'''SELECT p.product_category_name,SUM(ri.refund_qty) AS refund_units,SUM(ri.refund_value) AS refund_value FROM refund_items ri JOIN order_items oi ON oi.order_id=ri.order_id AND oi.order_item_id=ri.order_item_id LEFT JOIN products p ON p.product_id=oi.product_id GROUP BY p.product_category_name HAVING SUM(ri.refund_qty) IS NOT NULL ORDER BY refund_units DESC,p.product_category_name NULLS LAST LIMIT 18''','退款明细完整主键(refund_id,order_id,order_item_id)；匹配order_items必须同时使用order_id和order_item_id。')
add(4,'shipments,shipment_tracking,warehouses,regions', '按仓库所在地大区统计已有发货时间、且至少存在一条地点非NULL物流轨迹的运输记录数和其中未签收记录数。只输出大区和两个数量，大区升序NULL最后；同一运输记录多条轨迹只计一次，仓库缺失、州未映射保留NULL组，订单状态和运输状态不限，不以客户或卖家大区代替。',
'''SELECT r.macro_region,COUNT(*) AS shipped_records,COUNT(*) FILTER(WHERE s.delivered_at IS NULL) AS unsigned_records FROM shipments s LEFT JOIN warehouses w ON w.warehouse_id=s.warehouse_id LEFT JOIN regions r ON r.region_code=w.region_code WHERE s.shipped_at IS NOT NULL AND EXISTS(SELECT 1 FROM shipment_tracking tr WHERE tr.shipment_id=s.shipment_id AND tr.location IS NOT NULL) GROUP BY r.macro_region ORDER BY r.macro_region NULLS LAST''','一行一shipment_id；轨迹用EXISTS防扩行，空字符串地点属于非NULL；仓库归属来自warehouses.region_code，签收只看shipments.delivered_at。')
add(4,'support_tickets,ticket_categories,elapsed', '对2018年1月1日含至4月1日不含创建的工单，按工单分类ID及名称统计工单数和已解决工单平均处理小时数（2位小数）。输出分类ID、名称、工单数、平均小时，分类ID升序NULL最后；分类缺失保留未知组，解决时间为空者只不参与平均，不筛status。',
'''SELECT tc.category_id,tc.category_name,COUNT(*) AS ticket_count,ROUND(AVG(EXTRACT(EPOCH FROM(st.resolved_at-st.created_at))/3600.0),2) AS avg_hours FROM support_tickets st LEFT JOIN ticket_categories tc ON tc.category_id=st.category_id WHERE st.created_at>='2018-01-01' AND st.created_at<'2018-04-01' GROUP BY tc.category_id,tc.category_name ORDER BY tc.category_id NULLS LAST''','工单事实不可被消息表放大；EPOCH换算完整小数小时。')
add(4,'ticket_messages,support_tickets,zero', '在优先级为紧急（4）的工单中，取customer发送消息最多的前25张工单，零条也参与排序。只输出工单ID、订单号和customer消息数，消息数降序、工单ID升序；发送方按原始值精确匹配，不筛工单状态或日期。',
'''SELECT st.ticket_id,st.order_id,COUNT(tm.message_id) AS customer_message_count FROM support_tickets st LEFT JOIN ticket_messages tm ON tm.ticket_id=st.ticket_id AND tm.sender_type='customer' WHERE st.priority=4 GROUP BY st.ticket_id,st.order_id ORDER BY customer_message_count DESC,st.ticket_id LIMIT 25''','工单ID为输出身份，COUNT消息主键保留无消息工单为0。')
add(4,'brands,product_brand_map,products', '列出全部品牌及其当前归属商品数量，仅is_current=true的关联算当前，且商品必须真实存在。输出品牌ID、品牌名称、商品数，品牌ID升序；没有当前商品的品牌显示0，同一商品在多个品牌存在当前关联时分别计入各品牌，不猜唯一品牌。',
'''SELECT b.brand_id,b.brand_name,COUNT(p.product_id) AS current_product_count FROM brands b LEFT JOIN product_brand_map pb ON pb.brand_id=b.brand_id AND pb.is_current IS TRUE LEFT JOIN products p ON p.product_id=pb.product_id GROUP BY b.brand_id,b.brand_name ORDER BY b.brand_id''','关联主键(product_id,brand_id)防同一品牌重复项；不把历史品牌算当前。')
add(4,'products,product_price_history,category', '在原始类目已知的商品中，按类目统计2018年4月1日含至7月1日不含的调价次数，以及每条已知新旧价格调价的平均金额差（新价减旧价，2位小数）。只输出有调价的类目、调价次数、平均差，类目升序；每次变动等权，不先按商品平均，不输出百分比。',
'''SELECT p.product_category_name,COUNT(*) AS change_count,ROUND(AVG(h.new_price-h.old_price),2) AS avg_price_delta FROM product_price_history h JOIN products p ON p.product_id=h.product_id WHERE p.product_category_name IS NOT NULL AND h.changed_at>='2018-04-01' AND h.changed_at<'2018-07-01' GROUP BY p.product_category_name ORDER BY p.product_category_name''','COUNT含新旧价缺失的调价事实，平均值只含两价已知；粒度history_id。')
add(4,'orders,shipping_addresses,exists', '按订单customer_id对应的客户档案州统计2018年5月的全部订单数，但只计该customer_id至少存在一条默认收货地址且地址州与客户档案州相同的订单。输出客户档案州、订单数，州升序；包含取消和不可用状态，不按自然人扩大匹配，同一订单只计一次，NULL州不视为相同。',
'''SELECT c.customer_state,COUNT(*) AS order_count FROM orders o JOIN customers c ON c.customer_id=o.customer_id WHERE o.order_purchase_timestamp>='2018-05-01' AND o.order_purchase_timestamp<'2018-06-01' AND EXISTS(SELECT 1 FROM shipping_addresses a WHERE a.customer_id=o.customer_id AND a.is_default IS TRUE AND a.state=c.customer_state) GROUP BY c.customer_state ORDER BY c.customer_state''','EXISTS避免同一客户多个默认地址复制订单；地址和客户属性按事实customer_id准确归属。')
add(4,'members,user_tag_map,user_tags', '统计各用户标签对应的当前正常会员（status=1）人数，输出标签ID、标签编码、标签名称和会员数，标签ID升序。列出全部标签，没有正常会员的标签显示0；计量单位member_id，一个会员有多个标签可分别计入各标签。',
'''SELECT t.tag_id,t.tag_code,t.tag_name,COUNT(m.member_id) AS normal_member_count FROM user_tags t LEFT JOIN user_tag_map tm ON tm.tag_id=t.tag_id LEFT JOIN members m ON m.member_id=tm.member_id AND m.status=1 GROUP BY t.tag_id,t.tag_code,t.tag_name ORDER BY t.tag_id''','静态标签事实，不用首单月替代NEW_USER；user_tag_map主键防重复打标行。')
add(4,'referrals,members,member_levels', '按推荐人的当前会员等级统计推荐条数和已转化条数，只计能匹配到推荐人会员及等级定义的记录。输出等级ID、等级名称和两个条数，等级ID升序；转化看converted_at非NULL，不按被推荐人等级分组，不限制会员状态或订单状态。',
'''SELECT l.level_id,l.level_name,COUNT(*) AS referral_count,COUNT(r.converted_at) AS converted_count FROM referrals r JOIN members m ON m.member_id=r.referrer_member_id JOIN member_levels l ON l.level_id=m.level_id GROUP BY l.level_id,l.level_name ORDER BY l.level_id''','推荐人链referrer_member_id→members→member_levels，一条推荐计一次。')
add(4,'settlements,sellers,region', '按卖家州汇总2018年3月1日含至6月1日不含开始账期、且已打款（status=3）的结算单应结净额及结算单数，输出卖家州、净额、单数，州升序NULL最后；卖家匹配缺失保留NULL组，按period_start选账期，不按paid_at筛选。',
'''SELECT s.seller_state,SUM(st.net_amount) AS net_total,COUNT(*) AS settlement_count FROM settlements st LEFT JOIN sellers s ON s.seller_id=st.seller_id WHERE st.status=3 AND st.period_start>='2018-03-01' AND st.period_start<'2018-06-01' GROUP BY s.seller_state ORDER BY s.seller_state NULLS LAST''','使用结算单净额，不连接明细复制金额，也不再次扣佣金/运费。')
add(4,'settlement_items,order_items,products', '按商品原始类目汇总结算明细的毛额和佣金金额，取已知毛额合计最高16组。只计能按订单号和明细序号匹配的结算明细，商品类目未知保留NULL组。输出类目、毛额、佣金，毛额降序、类目升序NULL最后；不筛订单或结算状态，不重算佣金。',
'''SELECT p.product_category_name,SUM(si.gross_amount) AS gross_total,SUM(si.commission_amount) AS commission_total FROM settlement_items si JOIN order_items oi ON oi.order_id=si.order_id AND oi.order_item_id=si.order_item_id LEFT JOIN products p ON p.product_id=oi.product_id GROUP BY p.product_category_name HAVING SUM(si.gross_amount) IS NOT NULL ORDER BY gross_total DESC,p.product_category_name NULLS LAST LIMIT 16''','结算明细完整主键(settlement_id,order_id,order_item_id)，毛额和佣金是已有财务事实。')
add(4,'search_logs,products,translation', '在2018年7月的有点击搜索日志中，按点击商品的英文类目统计日志条数，取最多的前15组。输出英文类目、日志条数，条数降序、英文类目升序NULL最后；商品匹配缺失、原始类目NULL或无翻译均保留在NULL英文组，不按会员或商品去重。',
'''SELECT t.product_category_name_english,COUNT(*) AS clicked_searches FROM search_logs sl LEFT JOIN products p ON p.product_id=sl.clicked_product_id LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name WHERE sl.clicked_product_id IS NOT NULL AND sl.searched_at>='2018-07-01' AND sl.searched_at<'2018-08-01' GROUP BY t.product_category_name_english ORDER BY clicked_searches DESC,t.product_category_name_english NULLS LAST LIMIT 15''','事实身份log_id；英文缺失不排除点击日志，不用内连接吞未知事实。')
add(4,'inventory_movements,warehouses,products', '统计2018年8月仓库所在州为SP的退货入库流水（movement_type=3），按商品原始类目汇总数量和流水条数。输出类目、数量、条数，类目升序NULL最后；仓库必须匹配，商品缺失或类目NULL保留未知组，数量按原始值相加，不按订单状态筛选。',
'''SELECT p.product_category_name,SUM(im.quantity) AS returned_quantity,COUNT(*) AS movement_count FROM inventory_movements im JOIN warehouses w ON w.warehouse_id=im.warehouse_id LEFT JOIN products p ON p.product_id=im.product_id WHERE w.region_code='SP' AND im.movement_type=3 AND im.moved_at>='2018-08-01' AND im.moved_at<'2018-09-01' GROUP BY p.product_category_name ORDER BY p.product_category_name NULLS LAST''','仓库州来源warehouses.region_code；一行一movement_id，不从退货订单猜库存流水。')
add(4,'order_payments,orders,customers', '对2018年第一季度下单的全部订单，按该订单customer_id对应客户记录的州汇总借记卡付款金额及借记卡支付记录条数。输出客户州、付款金额、支付条数，州升序NULL最后；包含取消和不可用订单，未知客户州保留，金额用payment_value，不加运费。',
'''SELECT c.customer_state,SUM(op.payment_value) AS paid_amount,COUNT(*) AS payment_count FROM order_payments op JOIN orders o ON o.order_id=op.order_id LEFT JOIN customers c ON c.customer_id=o.customer_id WHERE op.payment_type='debit_card' AND o.order_purchase_timestamp>='2018-01-01' AND o.order_purchase_timestamp<'2018-04-01' GROUP BY c.customer_state ORDER BY c.customer_state NULLS LAST''','支付主键(order_id,payment_sequential)一次；州沿订单客户键归属，不跨自然人多档案匹配。')
add(4,'order_reviews,order_items,products,grain', '对全部订单状态的评价，按订单包含的原始商品类目统计评价记录数和评分不高于2的评价记录数。排除原始NULL类目；同一条评价在同一类目只计一次，跨多个类目可分别计入。只输出类目和两个数量，类目升序，不计算百分比。',
'''WITH x AS (SELECT DISTINCT r.review_id,r.order_id,r.review_score,p.product_category_name FROM order_reviews r JOIN order_items oi ON oi.order_id=r.order_id JOIN products p ON p.product_id=oi.product_id WHERE p.product_category_name IS NOT NULL) SELECT product_category_name,COUNT(*) AS review_count,COUNT(*) FILTER(WHERE review_score<=2) AS low_score_count FROM x GROUP BY product_category_name ORDER BY product_category_name''','评价去重身份(review_id,order_id)加类目；不是按review_id单键，也不是按商品行给评价加权。')
add(4,'campaigns,campaign_products,orders,items', '对2018年开始的各营销活动，统计活动商品在该活动开始日至结束日（两端含整日）内下单的有效订单商品行数和商品金额（不含运费）。只输出有匹配商品行的活动ID、名称、商品行数、金额，活动ID升序；有效订单排除取消和不可用，同一商品属于多个活动时各活动独立计入。',
'''SELECT c.campaign_id,c.campaign_name,COUNT(*) AS item_rows,SUM(oi.price) AS product_amount FROM campaigns c JOIN campaign_products cp ON cp.campaign_id=c.campaign_id JOIN order_items oi ON oi.product_id=cp.product_id JOIN orders o ON o.order_id=oi.order_id WHERE c.start_date>='2018-01-01' AND c.start_date<'2019-01-01' AND c.end_date IS NOT NULL AND o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>=c.start_date AND o.order_purchase_timestamp<c.end_date+INTERVAL '1 day' GROUP BY c.campaign_id,c.campaign_name ORDER BY c.campaign_id''','活动维度身份campaign_id，活动商品主键防同活动重复产品；不声称销售归因是独占因果效果。')

# T5: deep cross-domain paths with independent fact pre-aggregation.
add(5,'refunds,items,products,brands,regions', '对2018年上半年申请的已退款（status=4）退款明细，按原商品当前品牌及原卖家所在地大区汇总退款件数、退款明细金额。只输出品牌ID、品牌名称、大区、退款件数、退款金额，品牌ID升序NULL最后再大区升序NULL最后；订单状态不限、金额不加运费。只计能匹配原订单商品行的退款明细；无当前品牌或未知地域保留NULL组，若商品多个当前品牌则分别计入各品牌，不声称各品牌合计等于全站。',
'''SELECT b.brand_id,b.brand_name,rg.macro_region,SUM(ri.refund_qty) AS refund_units,SUM(ri.refund_value) AS refund_value FROM refunds r JOIN refund_items ri ON ri.refund_id=r.refund_id AND ri.order_id=r.order_id JOIN order_items oi ON oi.order_id=ri.order_id AND oi.order_item_id=ri.order_item_id LEFT JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_brand_map pb ON pb.product_id=p.product_id AND pb.is_current IS TRUE LEFT JOIN brands b ON b.brand_id=pb.brand_id LEFT JOIN sellers s ON s.seller_id=oi.seller_id LEFT JOIN regions rg ON rg.region_code=s.seller_state WHERE r.status=4 AND r.requested_at>='2018-01-01' AND r.requested_at<'2018-07-01' GROUP BY b.brand_id,b.brand_name,rg.macro_region ORDER BY b.brand_id NULLS LAST,rg.macro_region NULLS LAST''','退款明细金额是refund_value；品牌为当前关联、地区为原卖家，连接原明细必须完整二键；行数须实库验证≤500。')
add(5,'shipments,warehouse,region,member,tags', '按仓库所在地大区统计2018年3月至5月发货的运输记录数，仅计其订单自然人当前属于正常会员（status=1），且该会员存在CHURN_RISK标签的记录。只输出大区、运输记录数，大区升序NULL最后；沿订单customer_id定位自然人，重复标签或多客户档案不得放大运输记录，仓库地域未知保留NULL组，订单状态不限。',
'''SELECT rg.macro_region,COUNT(*) AS shipment_count FROM shipments s JOIN orders o ON o.order_id=s.order_id JOIN customers c ON c.customer_id=o.customer_id JOIN members m ON m.customer_unique_id=c.customer_unique_id LEFT JOIN warehouses w ON w.warehouse_id=s.warehouse_id LEFT JOIN regions rg ON rg.region_code=w.region_code WHERE s.shipped_at>='2018-03-01' AND s.shipped_at<'2018-06-01' AND m.status=1 AND EXISTS(SELECT 1 FROM user_tag_map ut JOIN user_tags t ON t.tag_id=ut.tag_id WHERE ut.member_id=m.member_id AND t.tag_code='CHURN_RISK') GROUP BY rg.macro_region ORDER BY rg.macro_region NULLS LAST''','事实shipment_id；人连接用于会员筛选，仓库维度不经客户州；标签用EXISTS。')
add(5,'coupon_usages,campaigns,member_levels,multi_fact', '对2018年第二季度核销、订单也在同一季度下单的用券有效订单，按券所属活动和用券记录会员的当前等级汇总核销优惠金额与不同订单数。只计券、活动、会员、等级都匹配的核销记录，输出活动ID、活动名称、等级ID、等级名称、优惠金额、订单数，活动ID和等级ID升序；有效订单排除取消与不可用，不用订单买家的会员替换核销记录member_id。',
'''SELECT ca.campaign_id,ca.campaign_name,ml.level_id,ml.level_name,SUM(cu.discount_amount) AS discount_total,COUNT(DISTINCT cu.order_id) AS order_count FROM coupon_usages cu JOIN coupons cp ON cp.coupon_id=cu.coupon_id JOIN campaigns ca ON ca.campaign_id=cp.campaign_id JOIN members m ON m.member_id=cu.member_id JOIN member_levels ml ON ml.level_id=m.level_id JOIN orders o ON o.order_id=cu.order_id WHERE cu.used_at>='2018-04-01' AND cu.used_at<'2018-07-01' AND o.order_purchase_timestamp>='2018-04-01' AND o.order_purchase_timestamp<'2018-07-01' AND o.order_status NOT IN ('canceled','unavailable') GROUP BY ca.campaign_id,ca.campaign_name,ml.level_id,ml.level_name ORDER BY ca.campaign_id,ml.level_id''','优惠事实一核销一次；订单数组内去重，活动/等级归属来自核销链；不接商品明细扩大优惠。')
add(5,'settlements,items,sellers,regions,translation', '对2018年1月至3月开始账期的结算明细，按卖家所在地大区和商品英文类目汇总财务毛额、佣金金额，只输出这两个维度及两个金额。要求结算单、其卖家、原订单商品行和商品均匹配，地区或翻译缺失保留NULL组；不筛订单或结算状态，按大区再英文类目升序NULL最后，不从商品价格重算财务金额。',
'''SELECT rg.macro_region,t.product_category_name_english,SUM(si.gross_amount) AS gross_total,SUM(si.commission_amount) AS commission_total FROM settlement_items si JOIN settlements st ON st.settlement_id=si.settlement_id JOIN sellers s ON s.seller_id=st.seller_id JOIN order_items oi ON oi.order_id=si.order_id AND oi.order_item_id=si.order_item_id JOIN products p ON p.product_id=oi.product_id LEFT JOIN regions rg ON rg.region_code=s.seller_state LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name WHERE st.period_start>='2018-01-01' AND st.period_start<'2018-04-01' GROUP BY rg.macro_region,t.product_category_name_english ORDER BY rg.macro_region NULLS LAST,t.product_category_name_english NULLS LAST''','财务明细主键(settlement_id,order_id,order_item_id)，卖家维度沿settlements.seller_id；未知类目保留。')
add(5,'support_tickets,messages,orders,customer,regions', '统计2018年6月创建的工单，按该工单order_id对应订单customer_id的客户所在大区汇总工单数和customer消息总条数。只计存在订单及客户档案的工单，地区缺失保留NULL组；无customer消息的工单贡献0条。输出大区、工单数、customer消息数，大区升序NULL最后；订单与工单状态不限。',
'''WITH msg AS (SELECT ticket_id,COUNT(*) AS n FROM ticket_messages WHERE sender_type='customer' GROUP BY ticket_id) SELECT rg.macro_region,COUNT(*) AS ticket_count,SUM(COALESCE(msg.n,0)) AS customer_message_count FROM support_tickets st JOIN orders o ON o.order_id=st.order_id JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN regions rg ON rg.region_code=c.customer_state LEFT JOIN msg ON msg.ticket_id=st.ticket_id WHERE st.created_at>='2018-06-01' AND st.created_at<'2018-07-01' GROUP BY rg.macro_region ORDER BY rg.macro_region NULLS LAST''','消息先按ticket_id聚合，避免消息数给工单加权；客户属性不沿工单会员反向扩散至全部客户档案。')
add(5,'search_logs,member_levels,brands,products', '对2018年8月有点击的搜索日志，按搜索会员当前等级及点击商品当前品牌统计日志条数。只计能匹配会员、等级和商品的日志；无当前品牌保留NULL品牌，商品多当前品牌时分别计数。输出等级ID、等级名称、品牌ID、品牌名称、日志条数，等级ID、品牌ID升序NULL最后；未知会员日志排除，不按会员去重。',
'''SELECT l.level_id,l.level_name,b.brand_id,b.brand_name,COUNT(*) AS clicked_logs FROM search_logs sl JOIN members m ON m.member_id=sl.member_id JOIN member_levels l ON l.level_id=m.level_id JOIN products p ON p.product_id=sl.clicked_product_id LEFT JOIN product_brand_map pb ON pb.product_id=p.product_id AND pb.is_current IS TRUE LEFT JOIN brands b ON b.brand_id=pb.brand_id WHERE sl.clicked_product_id IS NOT NULL AND sl.searched_at>='2018-08-01' AND sl.searched_at<'2018-09-01' GROUP BY l.level_id,l.level_name,b.brand_id,b.brand_name ORDER BY l.level_id,b.brand_id NULLS LAST''','计量为日志×当前品牌关联；品牌非独占，不能将跨品牌数机械相加当全站去重日志。')
add(5,'inventory,inventory_movements,warehouses,regions,translation', '按仓库所在地大区与商品英文类目，对库存表当前存在的仓库商品项统计当前库存合计和2018年9月的出库数量合计。只计仓库及商品均匹配的当前项，地区与翻译缺失保留NULL组；没有该月出库的当前项按0出库计。输出大区、英文类目、库存量、出库量，两个维度升序NULL最后；出库类型=2且原数量求和，库存NULL不补0。',
'''WITH mv AS (SELECT warehouse_id,product_id,SUM(quantity) AS qty FROM inventory_movements WHERE movement_type=2 AND moved_at>='2018-09-01' AND moved_at<'2018-10-01' GROUP BY warehouse_id,product_id) SELECT rg.macro_region,t.product_category_name_english,SUM(i.quantity) AS stock_qty,SUM(CASE WHEN mv.product_id IS NULL THEN 0 ELSE mv.qty END) AS outbound_qty FROM inventory i JOIN warehouses w ON w.warehouse_id=i.warehouse_id JOIN products p ON p.product_id=i.product_id LEFT JOIN regions rg ON rg.region_code=w.region_code LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name LEFT JOIN mv ON mv.warehouse_id=i.warehouse_id AND mv.product_id=i.product_id GROUP BY rg.macro_region,t.product_category_name_english ORDER BY rg.macro_region NULLS LAST,t.product_category_name_english NULLS LAST''','当前库存与流水先在仓库商品同粒度对齐；只对可证明无出库行的项补0，有出库但全部数量未知仍NULL。')
add(5,'orders,items,payments,refunds,customer,regions', '对2018年4月下单的全部订单，按订单customer_id对应客户记录所在大区分别汇总商品金额（不含运费）、支付金额、退款单申请金额和订单数。只输出大区及四指标，大区升序NULL最后；没有对应事实记录的订单，该项贡献0；存在事实但金额全未知不强制补0。三个事实各自先按订单汇总，不限制支付/退款发生时间或状态，未知地区保留。',
'''WITH it AS (SELECT order_id,SUM(price) AS v FROM order_items GROUP BY order_id), pay AS (SELECT order_id,SUM(payment_value) AS v FROM order_payments GROUP BY order_id), rf AS (SELECT order_id,SUM(refund_amount) AS v FROM refunds GROUP BY order_id) SELECT rg.macro_region,SUM(CASE WHEN it.order_id IS NULL THEN 0 ELSE it.v END) AS product_amount,SUM(CASE WHEN pay.order_id IS NULL THEN 0 ELSE pay.v END) AS paid_amount,SUM(CASE WHEN rf.order_id IS NULL THEN 0 ELSE rf.v END) AS refund_amount,COUNT(*) AS order_count FROM orders o LEFT JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN regions rg ON rg.region_code=c.customer_state LEFT JOIN it ON it.order_id=o.order_id LEFT JOIN pay ON pay.order_id=o.order_id LEFT JOIN rf ON rf.order_id=o.order_id WHERE o.order_purchase_timestamp>='2018-04-01' AND o.order_purchase_timestamp<'2018-05-01' GROUP BY rg.macro_region ORDER BY rg.macro_region NULLS LAST''','订单粒度预聚合防商品×支付×退款笛卡尔放大；未知事实金额不偷换成已知0，不计算净额。')
add(5,'referrals,members,levels,tags,cohort', '统计2018年上半年创建的推荐，按推荐人当前等级分组，只计被推荐人当前有HIGH_VALUE标签且两端会员及推荐人等级都真实存在的记录。输出等级ID、等级名称、推荐条数、已转化条数和奖励总额，等级ID升序；奖励取全部入选推荐原始reward_amount，NULL忽略，未转化记录不删除，不按被推荐人人数去重。',
'''SELECT l.level_id,l.level_name,COUNT(*) AS referral_count,COUNT(r.converted_at) AS converted_count,SUM(r.reward_amount) AS reward_total FROM referrals r JOIN members src ON src.member_id=r.referrer_member_id JOIN member_levels l ON l.level_id=src.level_id JOIN members dst ON dst.member_id=r.invitee_member_id WHERE r.created_at>='2018-01-01' AND r.created_at<'2018-07-01' AND EXISTS(SELECT 1 FROM user_tag_map ut JOIN user_tags t ON t.tag_id=ut.tag_id WHERE ut.member_id=dst.member_id AND t.tag_code='HIGH_VALUE') GROUP BY l.level_id,l.level_name ORDER BY l.level_id''','推荐人和被推荐人两条身份链不可混淆；标签EXISTS确保不复制推荐奖励。')
add(5,'orders,products,translation,customer,member_levels', '对2018年7月下单的有效订单，按买家当前会员等级和商品英文类目汇总商品行数与含运费金额。只计买家能通过订单customer_id定位自然人并匹配当前会员、等级的订单明细；商品必须存在，无翻译或原始类目未知保留NULL英文组。输出等级ID、等级名称、英文类目、商品行数、含运费金额，等级ID及英文类目升序NULL最后；有效订单排除取消和不可用。',
'''SELECT l.level_id,l.level_name,t.product_category_name_english,COUNT(*) AS item_rows,SUM(oi.price+oi.freight_value) AS amount_with_freight FROM orders o JOIN customers c ON c.customer_id=o.customer_id JOIN members m ON m.customer_unique_id=c.customer_unique_id JOIN member_levels l ON l.level_id=m.level_id JOIN order_items oi ON oi.order_id=o.order_id JOIN products p ON p.product_id=oi.product_id LEFT JOIN product_category_translation t ON t.product_category_name=p.product_category_name WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-07-01' AND o.order_purchase_timestamp<'2018-08-01' GROUP BY l.level_id,l.level_name,t.product_category_name_english ORDER BY l.level_id,t.product_category_name_english NULLS LAST''','会员等级是当前状态，不冒充下单时等级；金额在商品行粒度，任一组成NULL的行不贡献已知含运费金额。')

# T6: metric contracts selected without reading candidate implementations or failures.
add(6,'repeat_rate,identity,denominator', '计算2018年2月1日含至8月1日不含期间，订单所关联客户记录州为MG的有效订单买家复购率。按已知customer_unique_id识别自然人，同一人在该范围内至少2笔有效订单算复购买家，分母是该范围全部下过有效订单的已知自然人。只输出复购率，单位0至100百分数保留2位；无买家返回NULL，有效订单排除取消和不可用。',
'''WITH p AS (SELECT c.customer_unique_id,COUNT(*) AS n FROM orders o JOIN customers c ON c.customer_id=o.customer_id WHERE o.order_status NOT IN ('canceled','unavailable') AND c.customer_unique_id IS NOT NULL AND c.customer_state='MG' AND o.order_purchase_timestamp>='2018-02-01' AND o.order_purchase_timestamp<'2018-08-01' GROUP BY c.customer_unique_id) SELECT ROUND(100.0*COUNT(*) FILTER(WHERE n>=2)/NULLIF(COUNT(*),0),2) AS repeat_pct FROM p''','地域按各笔订单的客户关联键，先限定集合再按自然人聚合；未知身份不当一个人。')
add(6,'aov,gmv,freight', '计算2018年5月的有效订单客单价，范围仅限至少有一行商品明细的订单；GMV按商品金额加运费合计，分母是这些有效订单的订单数，不是人数或商品行数。只输出客单价金额，2位小数；无订单返回NULL，有效订单排除取消与不可用。',
'''WITH ot AS (SELECT order_id,SUM(price+freight_value) AS gmv FROM order_items GROUP BY order_id) SELECT ROUND(SUM(ot.gmv)/NULLIF(COUNT(*),0),2) AS aov FROM orders o JOIN ot ON ot.order_id=o.order_id WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-05-01' AND o.order_purchase_timestamp<'2018-06-01' ''','先一单一金额再计订单；金额未知不补0，含运费表达式每行price+freight_value。')
add(6,'member_penetration,current_members,region', '按订单客户所在州计算2018年第一季度的会员订单渗透率，只输出客户州、会员订单占比，州升序NULL最后。分母为各州全部有效订单，分子为其中自然人存在当前会员记录的有效订单，不限会员状态，订单客户或身份未知仍在分母。单位0至100百分数2位，无有效订单不输出州；排除取消和不可用，不把当前会员身份说成历史入会身份。',
'''SELECT c.customer_state,ROUND(100.0*COUNT(*) FILTER(WHERE EXISTS(SELECT 1 FROM members m WHERE m.customer_unique_id=c.customer_unique_id))/NULLIF(COUNT(*),0),2) AS member_order_pct FROM orders o LEFT JOIN customers c ON c.customer_id=o.customer_id WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-01-01' AND o.order_purchase_timestamp<'2018-04-01' GROUP BY c.customer_state ORDER BY c.customer_state NULLS LAST''','会员EXISTS身份标记不删除非会员；一行一订单，州来自该订单客户档案。')
add(6,'on_time_rate,timestamp_denominator,percent', '计算2018年4月1日含至7月1日不含下单的全部订单的准时送达率，只输出准时率，0至100百分数保留2位。分母为实际签收时间非NULL的订单，分子为实际签收不晚于预计送达的订单；预计时间未知的已签收订单留在分母但不入分子。包含取消和不可用状态，不用order_status判断签收；分母为0返回NULL。',
'''SELECT ROUND(100.0*COUNT(*) FILTER(WHERE order_delivered_customer_date IS NOT NULL AND order_delivered_customer_date<=order_estimated_delivery_date)/NULLIF(COUNT(*) FILTER(WHERE order_delivered_customer_date IS NOT NULL),0),2) AS on_time_pct FROM orders WHERE order_purchase_timestamp>='2018-04-01' AND order_purchase_timestamp<'2018-07-01' ''','按真实时间事实一订单一次；未知预计时间不当迟到或准时，不做1减逾期比例。')
add(6,'freight_ratio,gmv,seller_region', '按卖家所在地大区计算2018年上半年有效订单商品行的运费占GMV比例，GMV含运费。只输出大区和运费占比，0至100百分数2位，大区升序NULL最后。大区未知保留，分母是同组商品金额加运费合计，分子是同组运费合计，分母为0或未知返回NULL；有效订单排除取消和不可用。',
'''SELECT r.macro_region,ROUND(100.0*SUM(oi.freight_value)/NULLIF(SUM(oi.price+oi.freight_value),0),2) AS freight_pct FROM orders o JOIN order_items oi ON oi.order_id=o.order_id LEFT JOIN sellers s ON s.seller_id=oi.seller_id LEFT JOIN regions r ON r.region_code=s.seller_state WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-01-01' AND o.order_purchase_timestamp<'2018-07-01' GROUP BY r.macro_region ORDER BY r.macro_region NULLS LAST''','商品行粒度沿卖家州归属，非客户州；采用总运费/总GMV而非行比例平均。')
add(6,'discount_rate,preaggregate,multi_fact', '计算2018年6月下单、至少有一条用券记录且至少有一行商品明细的有效订单的用券折扣率。每单所有核销优惠金额先合计，GMV为该单所有商品金额加运费合计，再用入选订单总优惠除以总GMV。只输出折扣率，0至100百分数2位，分母为0或未知返回NULL；核销时间不限，排除取消和不可用订单，不按商品行复制优惠。',
'''WITH u AS (SELECT order_id,SUM(discount_amount) AS discount_total FROM coupon_usages GROUP BY order_id), it AS (SELECT order_id,SUM(price+freight_value) AS gmv FROM order_items GROUP BY order_id) SELECT ROUND(100.0*SUM(u.discount_total)/NULLIF(SUM(it.gmv),0),2) AS discount_pct FROM orders o JOIN u ON u.order_id=o.order_id JOIN it ON it.order_id=o.order_id WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-06-01' AND o.order_purchase_timestamp<'2018-07-01' ''','两种一对多事实先各自一单一行再join；金额NULL忽略，不以SUM(DISTINCT金额)消重。')
add(6,'retention_rate,cohort,calendar', '计算首次有效下单自然月为2017年11月的已知自然人买家，在2018年1月是否再次下有效订单的留存率。首单从全历史有效订单判定，回访窗口为2018年1月1日含至2月1日不含；分母为整个2017年11月首单人群，分子为该人群中至少回访一次的人数。只输出留存率，0至100百分数2位，空人群返回NULL；有效订单排除取消和不可用，不按customer_id当人。',
'''WITH v AS (SELECT c.customer_unique_id,o.order_purchase_timestamp AS t FROM orders o JOIN customers c ON c.customer_id=o.customer_id WHERE o.order_status NOT IN ('canceled','unavailable') AND c.customer_unique_id IS NOT NULL AND o.order_purchase_timestamp IS NOT NULL), f AS (SELECT customer_unique_id,MIN(t) AS first_t FROM v GROUP BY customer_unique_id), cohort AS (SELECT customer_unique_id FROM f WHERE first_t>='2017-11-01' AND first_t<'2017-12-01'), returned AS (SELECT DISTINCT customer_unique_id FROM v WHERE t>='2018-01-01' AND t<'2018-02-01') SELECT ROUND(100.0*COUNT(returned.customer_unique_id)/NULLIF(COUNT(*),0),2) AS retention_pct FROM cohort LEFT JOIN returned ON returned.customer_unique_id=cohort.customer_unique_id''','这是指定隔月窗口，不是次月留存；去重回访身份集合标记回访，未回访者留作分母。')
add(6,'customer_cohort,dynamic,gmv', '统计2018年3月至5月每个自然月按动态新老客贡献的有效订单数和含运费GMV，输出月份YYYY-MM、新老客类别NEW或RETURNING或NULL、订单数、GMV；月份升序，再类别升序NULL最后。动态分类按全历史该自然人首次有效下单月：同月所有有效订单为NEW，后续月为RETURNING；身份或首月未知单列NULL组，不用NEW_USER静态标签。保留无商品明细订单计数，此类订单对GMV贡献0；存在明细但金额全未知不补0。',
'''WITH f AS (SELECT c.customer_unique_id,DATE_TRUNC('month',MIN(o.order_purchase_timestamp)) AS first_month FROM orders o JOIN customers c ON c.customer_id=o.customer_id WHERE o.order_status NOT IN ('canceled','unavailable') AND c.customer_unique_id IS NOT NULL AND o.order_purchase_timestamp IS NOT NULL GROUP BY c.customer_unique_id), it AS (SELECT order_id,SUM(price+freight_value) AS gmv FROM order_items GROUP BY order_id), x AS (SELECT DATE_TRUNC('month',o.order_purchase_timestamp) AS month,CASE WHEN c.customer_unique_id IS NULL OR f.first_month IS NULL THEN NULL WHEN DATE_TRUNC('month',o.order_purchase_timestamp)=f.first_month THEN 'NEW' WHEN DATE_TRUNC('month',o.order_purchase_timestamp)>f.first_month THEN 'RETURNING' ELSE NULL END AS cohort,CASE WHEN it.order_id IS NULL THEN 0 ELSE it.gmv END AS gmv FROM orders o LEFT JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN f ON f.customer_unique_id=c.customer_unique_id LEFT JOIN it ON it.order_id=o.order_id WHERE o.order_status NOT IN ('canceled','unavailable') AND o.order_purchase_timestamp>='2018-03-01' AND o.order_purchase_timestamp<'2018-06-01') SELECT TO_CHAR(month,'YYYY-MM') AS month,cohort,COUNT(*) AS order_count,SUM(gmv) AS gmv FROM x GROUP BY month,cohort ORDER BY month,cohort NULLS LAST''','首月由全历史确定，报告期只过滤输出事实；金额和订单先统一一单一行；不补不存在的月份或类别组合。')
add(6,'sla_rate,categories,all_tickets', '按工单分类计算2018年第二季度创建工单的SLA达成率，只计能匹配分类定义的工单。只输出分类ID、名称、达成率，分类ID升序；分母为该分类全部入选工单，未解决也在分母；已解决且完整处理小时不超过分类sla_hours才入分子。单位0至100百分数2位，未知sla_hours不能判达成，不补没有工单的分类。',
'''SELECT tc.category_id,tc.category_name,ROUND(100.0*COUNT(*) FILTER(WHERE st.resolved_at IS NOT NULL AND EXTRACT(EPOCH FROM(st.resolved_at-st.created_at))/3600.0<=tc.sla_hours)/NULLIF(COUNT(*),0),2) AS sla_pct FROM support_tickets st JOIN ticket_categories tc ON tc.category_id=st.category_id WHERE st.created_at>='2018-04-01' AND st.created_at<'2018-07-01' GROUP BY tc.category_id,tc.category_name ORDER BY tc.category_id''','一工单一次；没有消息连接加权，不以status=3替代真实resolved_at。')
add(6,'commission_rate,weighted_ratio,settlements', '计算2018年5月至7月开始账期的结算明细，按卖家州统计整体佣金率。分子用结算明细commission_amount合计，分母用同集合gross_amount合计，不平均单行佣金率。只输出卖家州与佣金率，单位0至1小数比率保留4位，州升序NULL最后；结算状态不限，卖家缺失保留NULL组，分母为0或未知返回NULL。',
'''SELECT s.seller_state,ROUND(SUM(si.commission_amount)/NULLIF(SUM(si.gross_amount),0),4) AS commission_ratio FROM settlement_items si JOIN settlements st ON st.settlement_id=si.settlement_id LEFT JOIN sellers s ON s.seller_id=st.seller_id WHERE st.period_start>='2018-05-01' AND st.period_start<'2018-08-01' GROUP BY s.seller_state ORDER BY s.seller_state NULLS LAST''','佣金率DECIMAL_RATIO而非百分数；金额是财务明细，不用settlements头金额乘明细行数。')
add(6,'search_ctr,member_levels,percent', '按搜索会员当前等级计算2018年9月搜索点击率，分母为该等级所有搜索日志，分子为clicked_product_id非NULL的日志。只计能匹配会员及等级定义的日志，不限会员状态；只输出等级ID、等级名称、点击率，0至100百分数2位，等级ID升序。不按人去重，也不要求点击商品存在，未出现搜索的等级不补0。',
'''SELECT l.level_id,l.level_name,ROUND(100.0*COUNT(*) FILTER(WHERE sl.clicked_product_id IS NOT NULL)/NULLIF(COUNT(*),0),2) AS click_pct FROM search_logs sl JOIN members m ON m.member_id=sl.member_id JOIN member_levels l ON l.level_id=m.level_id WHERE sl.searched_at>='2018-09-01' AND sl.searched_at<'2018-10-01' GROUP BY l.level_id,l.level_name ORDER BY l.level_id''','搜索事实log_id，点击证据是非NULL字段；不join products改变点击分母。')
add(6,'inventory_turnover,anchor,preaggregate', '按库存表的仓库ID计算库存周转天数，以全库库存流水最大moved_at为锚点，近90天定义为大于锚点减90天且小于等于锚点。分子为该仓当前quantity合计乘90，分母为该仓近90天movement_type=2的原始数量合计；库存和流水先分别按仓汇总。输出仓库ID和周转天数（1位小数），仓库ID升序；仅覆盖库存表出现的仓库，无出库、出库合计为0或未知均返回NULL，不使用今天日期，不把库存NULL补0。',
'''WITH a AS (SELECT MAX(moved_at) AS t FROM inventory_movements), st AS (SELECT warehouse_id,SUM(quantity) AS qty FROM inventory GROUP BY warehouse_id), mv AS (SELECT warehouse_id,SUM(quantity) AS qty FROM inventory_movements CROSS JOIN a WHERE movement_type=2 AND moved_at>a.t-INTERVAL '90 days' AND moved_at<=a.t GROUP BY warehouse_id) SELECT st.warehouse_id,ROUND(90.0*st.qty/NULLIF(mv.qty,0),1) AS turnover_days FROM st LEFT JOIN mv ON mv.warehouse_id=st.warehouse_id ORDER BY st.warehouse_id''','锚点全库统一，不每仓自取最大时间；两个事实先按仓聚合，避免库存项×流水放大。')

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def write_cases():
    expected=[20,20,16,22,10,12]
    assert [len(cases[n]) for n in range(1,7)]==expected
    OUT.mkdir(parents=True,exist_ok=True)
    paths=[]
    for n in range(1,7):
        path=OUT/f'T{n}_{GROUPS[n-1]}.yaml'
        # A JSON sequence is also valid YAML 1.2 and SnakeYAML accepts it unchanged.
        path.write_text(json.dumps(cases[n],ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
        paths.append(path)
    return paths

def dry_run(paths, only_ids=None):
    rows=[]
    all_ok=True
    previous={}
    if only_ids:
        previous={x['id']:x for x in json.loads((REPORT/'gold-dry-run-results.json').read_text(encoding='utf-8'))['cases']}
    for n in range(1,7):
        for c in cases[n]:
            if only_ids and c['id'] not in only_ids:
                rows.append(previous[c['id']])
                continue
            sql=c['gold_sql'].strip().rstrip(';')
            run_sql="BEGIN READ ONLY;\nSET LOCAL statement_timeout='8s';\nSELECT current_user,current_setting('transaction_read_only');\nSELECT COALESCE(json_agg(row_to_json(q)), '[]'::json) FROM ("+sql+") q;\nROLLBACK;\n"
            t=time.perf_counter()
            p=subprocess.run(['docker','exec','-i','text2sql-postgres','psql','-X','-qAt','-v','ON_ERROR_STOP=1','-U','text2sql_ro','-d','olist'],input=run_sql,text=True,encoding='utf-8',capture_output=True,timeout=30)
            elapsed=round((time.perf_counter()-t)*1000,2)
            item=dict(id=c['id'],returnCode=p.returncode,wallMs=elapsed,executionRole='text2sql_ro',readOnly=True,statementTimeout='8s')
            if c['id'] in previous:
                old=previous[c['id']]
                item['previousAttempts']=old.get('previousAttempts',[])+[{k:v for k,v in old.items() if k not in ['result','previousAttempts']}]
            if p.returncode:
                item.update(status='ERROR',error=p.stderr.strip())
                all_ok=False
            else:
                lines=[x for x in p.stdout.splitlines() if x.strip()]
                assert lines[0]=='text2sql_ro|on',lines[0]
                result=json.loads(lines[1])
                item.update(status='PASS' if len(result)<=500 else 'OVER_500',rowCount=len(result),result=result,resultSha256=hashlib.sha256(lines[1].encode('utf-8')).hexdigest())
                if len(result)>500: all_ok=False
            rows.append(item)
    (REPORT/'gold-dry-run-results.json').write_text(json.dumps(dict(cases=rows),ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
    summary=dict(total=len(rows),passed=sum(x['status']=='PASS' for x in rows),errors=sum(x['status']=='ERROR' for x in rows),over500=sum(x['status']=='OVER_500' for x in rows),emptyResults=sum(x.get('rowCount')==0 for x in rows),maxResultRows=max(x.get('rowCount',0) for x in rows),totalWallMs=round(sum(x['wallMs'] for x in rows),2),totalExecutions=sum(1+len(x.get('previousAttempts',[])) for x in rows),previousAttemptErrors=sum(a['status']=='ERROR' for x in rows for a in x.get('previousAttempts',[])),failedIds=[x['id'] for x in rows if x['status']!='PASS'])
    (REPORT/'gold-dry-run-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
    print(json.dumps(summary,ensure_ascii=False))
    return summary

def manifest(paths,summary):
    frozen=json.loads((ROOT/'reports/stage2-candidate-freeze-20261119/freeze.json').read_text(encoding='utf-8-sig'))
    manifest=dict(format='unseen-v2-authoring-manifest-v1',author=dict(agentRole='independent_unseen_v2_author',agentTask='/root/author_unseen_v2',freshContext=True,participatedInProductionTuning=False,participatedInEarlierQuestionAuthoring=False,independentReviewPerformedByAuthor=False),startedAt=STARTED,completedAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),candidate={k:frozen[k] for k in ['productionSourceCommit','sourceGitTree','promptVersion','currentCommit','frozenAt','jarSha256']},allowedSources=['Actual PostgreSQL public business schema, keys and read-only business data','src/main/resources/schema/metrics.yml','src/main/resources/schema/glossary.yml','src/main/resources/schema/ambiguities.yml','Freeze identity fields only'],excludedSources=['PromptTemplate','Production implementation','Historical model outputs','Old audit reports','Tuning history','Manual reading of data/eval, data/holdout, data/benchmarks, or old fewshot examples'],sourceLimitations=['Allowed business metadata contains historical examples and queryPattern text; new questions were authored from schema and explicit independent request combinations, without selecting candidate weaknesses.','Shared filesystem has no enforced OS read isolation; role separation is procedural.','Freeze file was read for identity and hashes; file listing of source paths was present but source contents were not read.'],files={str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in paths},quota={GROUPS[n-1]:len(cases[n]) for n in range(1,7)},total=100,dryRun=summary,duplicateCheck='See duplicate-check.json; programmatic exact normalized comparison only',providerCalls=0,externalLlmCalls=0,credentialsRead=False,databaseExecution=dict(container='text2sql-postgres',database='olist',user='text2sql_ro',transaction='BEGIN READ ONLY; SET LOCAL statement_timeout=8s; ... ROLLBACK;',allQueriesActuallyExecuted=True,resultsFile='reports/unseen-v2-authoring-20261119/gold-dry-run-results.json'),metadataSha256={str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in [ROOT/'src/main/resources/schema/metrics.yml',ROOT/'src/main/resources/schema/glossary.yml',ROOT/'src/main/resources/schema/ambiguities.yml']})
    manifest['duplicateCheck']=json.loads((REPORT/'duplicate-check.json').read_text(encoding='utf-8'))
    manifest['corpusSha256']=hashlib.sha256('\n'.join(p.name+':'+sha(p) for p in paths).encode('utf-8')).hexdigest()
    manifest['businessTablesCovered']=sorted(set(re.findall(r'(?i)\b(?:FROM|JOIN)\s+([a-z_][a-z_0-9]*)',' '.join(c['gold_sql'] for group in cases.values() for c in group)))-set(['a','st','mv','v','f','cohort','returned','it','u','ot','p','m','ranked','s','r','msg','rf','pay','x','order_purchase_timestamp','searched_at']))
    manifest['businessTableCoverageCount']=len(manifest['businessTablesCovered'])
    manifest['encoding']='UTF-8 without BOM; LF; JSON sequence syntax valid as YAML, verified with SnakeYAML 2.6'
    manifest['authoringChangesBeforeSeal']=['One Gold exceeded the 8s timeout in first dry-run; equivalent de-duplicated return-identity relation replaced repeated correlated scanning, followed by targeted rerun.','One relation question was expanded to cover the tracking domain and rerun.','Five initially empty-result draft conditions were changed using permitted real source-data distributions to increase discrimination; no model output or candidate failure was used.']
    manifest['independentReviewRequestedAuthorRevisions']=[dict(caseId='B2-T3-009',contractChange='Require a known, valid start/end interval before calendar-overlap selection.',goldChange='Added start_date<=end_date predicate.',verification='Targeted text2sql_ro read-only execution; independent reviewer remains responsible for acceptance.')]
    manifest['freezeManifestSha256']=sha(ROOT/'reports/stage2-candidate-freeze-20261119/freeze.json')
    manifest['reportSha256']={p.name:sha(p) for p in [REPORT/'gold-dry-run-results.json',REPORT/'gold-dry-run-summary.json',REPORT/'duplicate-check.json',REPORT/'author_cases.py',REPORT/'ExactOverlapCheck.java']}
    (REPORT/'authoring-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')

if __name__=='__main__':
    REPORT.mkdir(parents=True,exist_ok=True)
    if sys.argv[1:]==['--manifest-only']:
        manifest(sorted(OUT.glob('T*.yaml')),json.loads((REPORT/'gold-dry-run-summary.json').read_text(encoding='utf-8')))
        sys.exit(0)
    paths=write_cases()
    only_ids=set(sys.argv[1:]) or None
    summary=dry_run(paths,only_ids)
    manifest(paths,summary)
